def punch_aligned_bounds(now: datetime | None = None) -> tuple[datetime, datetime] | None:
    """当天随机上下班计划构成的绿点窗 [checkin_plan, checkout_plan)。"""
    now = _aware(now or datetime.now(_BJ))
    today = now.date()
    skip, _ = should_skip_punch(today)
    if skip:
        return None
    plans = ensure_daily_plans(today)
    start = plans.get('checkin')
    end = plans.get('checkout')
    if not start or not end:
        return None
    start, end = _aware(start), _aware(end)
    if end <= start:
        return None
    return start, end


def _rest_windows_today(day: date) -> list[tuple[str, str]]:
    return rest_windows_for_weekday(
        day.weekday(),
        weekday_raw=TG_WORK_ONLINE_REST_WINDOWS,
        saturday_raw=TG_WORK_ONLINE_REST_WINDOWS_SATURDAY,
    )


def _active_gaps(
    work_start: datetime,
    work_end: datetime,
    rest_windows: list[tuple[str, str]],
) -> list[tuple[datetime, datetime]]:
    """打卡窗外框减去午/晚休后的可闪烁区间（半开）。"""
    day = work_start.date()
    cuts: list[tuple[datetime, datetime]] = []
    for start_hhmm, end_hhmm in rest_windows:
        bounds = window_bounds(day, start_hhmm, end_hhmm)
        if not bounds:
            continue
        rs, re = bounds
        if re <= work_start or rs >= work_end:
            continue
        cuts.append((max(rs, work_start), min(re, work_end)))
    cuts.sort(key=lambda x: x[0])

    gaps: list[tuple[datetime, datetime]] = []
    cursor = work_start
    for rs, re in cuts:
        if rs > cursor:
            gaps.append((cursor, rs))
        cursor = max(cursor, re)
    if cursor < work_end:
        gaps.append((cursor, work_end))
    return [(a, b) for a, b in gaps if (b - a).total_seconds() >= _MIN_SEGMENT_SEC]


def _rand_duration_sec(lo: int, hi: int) -> int:
    lo = max(_MIN_SEGMENT_SEC, int(lo))
    hi = max(lo, int(hi))
    return lo + secrets.randbelow(hi - lo + 1)


def _offline_bounds() -> tuple[int, int]:
    hard = max(_MIN_SEGMENT_SEC, int(TG_PRESENCE_FLICKER_OFFLINE_HARD_CAP_SEC))
    lo = max(_MIN_SEGMENT_SEC, int(TG_PRESENCE_FLICKER_OFFLINE_MIN_SEC))
    hi = max(lo, int(TG_PRESENCE_FLICKER_OFFLINE_MAX_SEC))
    hi = min(hi, hard)
    lo = min(lo, hi)
    return lo, hi


def _online_bounds() -> tuple[int, int]:
    lo = max(_MIN_SEGMENT_SEC, int(TG_PRESENCE_FLICKER_ONLINE_MIN_SEC))
    hi = max(lo, int(TG_PRESENCE_FLICKER_ONLINE_MAX_SEC))
    return lo, hi


def _build_flicker_segments(
    gaps: list[tuple[datetime, datetime]],
) -> list[dict]:
    online_lo, online_hi = _online_bounds()
    offline_lo, offline_hi = _offline_bounds()
    segments: list[dict] = []
    # 首段偏在线（像刚到工位）；之后交替
    want_online = True
    for gap_start, gap_end in gaps:
        cursor = gap_start
        while cursor < gap_end:
            remaining = int((gap_end - cursor).total_seconds())
            if remaining <= 0:
                break
            if remaining < _MIN_SEGMENT_SEC:
                segments.append({
                    'start': cursor.isoformat(),
                    'end': gap_end.isoformat(),
                    'online': want_online,
                })
                break
            if want_online:
                dur = _rand_duration_sec(online_lo, online_hi)
            else:
                dur = _rand_duration_sec(offline_lo, offline_hi)
            dur = min(dur, remaining)
            seg_end = cursor + timedelta(seconds=dur)
            segments.append({
                'start': cursor.isoformat(),
                'end': seg_end.isoformat(),
                'online': want_online,
            })
            cursor = seg_end
            want_online = not want_online
    return segments


def _load_flicker_raw() -> dict:
    path = TG_PRESENCE_FLICKER_STATE_PATH
    if not os.path.isfile(path):
        return {}
    try:
        with open(path, encoding='utf-8') as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def _save_flicker(state: dict) -> None:
    os.makedirs(os.path.dirname(TG_PRESENCE_FLICKER_STATE_PATH), exist_ok=True)
    tmp = TG_PRESENCE_FLICKER_STATE_PATH + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(state, f, ensure_ascii=False, indent=2)
    os.replace(tmp, TG_PRESENCE_FLICKER_STATE_PATH)


def _purge_stale_flicker(state: dict, today: date) -> bool:
    changed = False
    cutoff = today - timedelta(days=_KEEP_PLAN_DAYS)
    for key in list(state.keys()):
        try:
            plan_day = date.fromisoformat(key)
        except ValueError:
            continue
        if plan_day < cutoff:
            del state[key]
            changed = True
    return changed


def _parse_segment(raw: dict) -> tuple[datetime, datetime, bool] | None:
    try:
        start = _aware(datetime.fromisoformat(raw['start']))
        end = _aware(datetime.fromisoformat(raw['end']))
        online = bool(raw['online'])
    except (KeyError, TypeError, ValueError):
        return None
    if end <= start:
        return None
    return start, end, online


def ensure_daily_flicker(day: date, *, force_new: bool = False) -> list[dict]:
    """生成/读取当日闪烁段；force_new 立刻重抽（部署后立即生效）。"""
    if not TG_PRESENCE_FLICKER_ENABLED:
        return []

    skip, reason = should_skip_punch(day)
    if skip:
        log.info('[presence-flicker] skip day=%s reason=%s', day.isoformat(), reason)
        return []

    bounds = punch_aligned_bounds(
        datetime(day.year, day.month, day.day, 12, 0, tzinfo=_BJ),
    )
    # punch_aligned_bounds uses now.date(); for explicit day pass via plans
    plans = ensure_daily_plans(day)
    start, end = plans.get('checkin'), plans.get('checkout')
    if not start or not end:
        return []
    start, end = _aware(start), _aware(end)
    if end <= start:
        return []

    with _FLICKER_LOCK:
        state = _load_flicker_raw()
        changed = _purge_stale_flicker(state, day)
        key = day.isoformat()
        if not force_new and key in state:
            entry = state[key]
            segs = entry.get('segments') if isinstance(entry, dict) else None
            if isinstance(segs, list) and segs:
                if changed:
                    _save_flicker(state)
                return segs

        gaps = _active_gaps(start, end, _rest_windows_today(day))
        segments = _build_flicker_segments(gaps)
        state[key] = {
            'generated_at': datetime.now(_BJ).isoformat(timespec='seconds'),
            'work_start': start.isoformat(),
            'work_end': end.isoformat(),
            'online_sec_range': list(_online_bounds()),
            'offline_sec_range': list(_offline_bounds()),
            'segments': segments,
        }
        _save_flicker(state)
        online_n = sum(1 for s in segments if s.get('online'))
        offline_n = len(segments) - online_n
        online_sec = sum(
            int((_aware(datetime.fromisoformat(s['end']))
                 - _aware(datetime.fromisoformat(s['start']))).total_seconds())
            for s in segments if s.get('online')
        )
        offline_sec = sum(
            int((_aware(datetime.fromisoformat(s['end']))
                 - _aware(datetime.fromisoformat(s['start']))).total_seconds())
            for s in segments if not s.get('online')
        )
        log.info(
            '[presence-flicker] day=%s segs=%d online_segs=%d offline_segs=%d '
            'online≈%dm offline≈%dm gaps=%d force_new=%s',
            key, len(segments), online_n, offline_n,
            online_sec // 60, offline_sec // 60, len(gaps), force_new,
        )
        return segments


def flicker_want_online(now: datetime | None = None) -> bool | None:
    """当前闪烁段是否该绿。None=未启用/无段（调用方回退为常绿）。"""
    if not TG_PRESENCE_FLICKER_ENABLED:
        return None
    now = _aware(now or datetime.now(_BJ))
    segments = ensure_daily_flicker(now.date())
    for raw in segments:
        parsed = _parse_segment(raw)
        if not parsed:
            continue
        start, end, online = parsed
        if start <= now < end:
            return online
    return False


def should_appear_online(now: datetime | None = None) -> bool:
    """别人看到的绿点是否该亮。

    顺序：请假/假日 → 午晚休灰 → 打卡窗外灰 → 闪烁段（约五五开，离线≤20min）。
    """
    now = _aware(now or datetime.now(_BJ))
    skip, _ = should_skip_punch(now.date())
    if skip:
        return False
    resting, _ = in_rest_window(
        now,
        windows=_rest_windows_today(now.date()),
    )
    if resting:
        return False
    bounds = punch_aligned_bounds(now)
    if not bounds:
        return False
    start, end = bounds
    if not (start <= now < end):
        return False
    flicker = flicker_want_online(now)
    if flicker is None:
        return True
    return flicker


async def _plan_refresh_loop(*, regenerate_flicker_today: bool = True) -> None:
    log.info(
        '[presence-plan] started checkin=%s~%s checkout=%s~%s sat_checkout=%s~%s '
        'flicker=%s online=%s-%ss offline=%s-%ss(cap=%ss)',
        TG_PRESENCE_CHECKIN_WINDOW_START,
        TG_PRESENCE_CHECKIN_WINDOW_END,
        TG_PRESENCE_CHECKOUT_WINDOW_START,
        TG_PRESENCE_CHECKOUT_WINDOW_END,
        TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_START,
        TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_END,
        TG_PRESENCE_FLICKER_ENABLED,
        TG_PRESENCE_FLICKER_ONLINE_MIN_SEC,
        TG_PRESENCE_FLICKER_ONLINE_MAX_SEC,
        TG_PRESENCE_FLICKER_OFFLINE_MIN_SEC,
        TG_PRESENCE_FLICKER_OFFLINE_MAX_SEC,
        TG_PRESENCE_FLICKER_OFFLINE_HARD_CAP_SEC,
    )
    last_plan_day: date | None = None
    boot_regen = regenerate_flicker_today
    while True:
        try:
            now = datetime.now(_BJ)
            today = now.date()
            if last_plan_day != today:
                plans = ensure_daily_plans(today)
                if plans:
                    parts = [f'{k}={v.strftime("%H:%M:%S")}' for k, v in sorted(plans.items())]
                    log.info('[presence-plan] today %s', ', '.join(parts))
                else:
                    skip, reason = should_skip_punch(today)
                    if skip:
                        log.info('[presence-plan] today off reason=%s', reason)
                ensure_daily_flicker(today, force_new=boot_regen)
                boot_regen = False
                last_plan_day = today
            await asyncio.sleep(3600)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.exception('[presence-plan] loop error: %s', exc)
            await asyncio.sleep(60)


async def start_presence_plan_scheduler() -> None:
    # 启动立刻重抽当日闪烁，满足「立刻按新计划闪」
    asyncio.create_task(_plan_refresh_loop(regenerate_flicker_today=True))


def summarize_flicker(day: date | None = None) -> str:
    """调试：打印当日闪烁摘要。"""
    day = day or datetime.now(_BJ).date()
    segs = ensure_daily_flicker(day)
    if not segs:
        return f'{day.isoformat()}: (no flicker segments)'
    lines = [f'{day.isoformat()}: {len(segs)} segments']
    for s in segs:
        flag = 'ON ' if s.get('online') else 'OFF'
        lines.append(f"  {flag} {s.get('start')} → {s.get('end')}")
    return '\n'.join(lines)


